from functools import lru_cache
import re
import time
import logging
import fnmatch
import argparse
import asyncio
import json
import sys

import carb
import carb.settings
import omni.kit.app
import omni.ext

logger = logging.getLogger(__name__)


REGISTRIES_SETTING = "/exts/omni.kit.registry.nucleus/registries"
USER_REGISTRIES_SETTING = "/persistent/exts/omni.kit.registry.nucleus/userRegistries"


def set_registries(urls):
    settings_dict = carb.settings.get_settings().get_settings_dictionary("")
    settings_dict[USER_REGISTRIES_SETTING[1:]] = []

    registries = []
    for i, url in enumerate(urls):
        registries.append({"name": f"registry_{i}", "url": url})

    settings_dict[REGISTRIES_SETTING[1:]] = registries


def list_exts(options):
    if options.registry_urls:
        set_registries(options.registry_urls)

    manager = omni.kit.app.get_app().get_extension_manager()
    manager.sync_registry()


    def get_packages():
        if options.name:
            ext_name, ext_version = omni.ext.get_extension_name_and_version(options.name)
            for p in manager.fetch_extension_packages(ext_name):
                if ext_version and p["id"] != options.name:
                    continue
                yield p
        else:
            for p in manager.fetch_all_extension_packages():
                yield p

    def get_and_filter_packages():
        for package in get_packages():
            is_remote = not package.get("path", "")
            if not is_remote and not options.include_local:
                continue
            yield package

    packages = list(get_and_filter_packages())

    print("-" * 120)
    print(f"Found {len(packages)} packages:")
    print("-" * 120)

    for i, package in enumerate(packages):
        package_id = package["package_id"]
        # left align number
        print(f"[{i}] {package_id}")
        if options.metadata:
            metadata = manager.get_registry_extension_dict(package_id) or manager.get_extension_dict(package_id)
            print(json.dumps(metadata.get_dict(), indent=2))

    print("-" * 120)

def browse_exts(options) -> bool:
    all_good = True

    if options.command == "list":
        list_exts(options)

    omni.kit.app.get_app().post_quit(0 if all_good else -3)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="command")

    # add list subprarser:
    list_parser = subparsers.add_parser("list")

    # positional argument:
    list_parser.add_argument("name", nargs="?", help="Extension name or name-version to filter by. E.g. 'omni.foo' or 'omni.foo-1.2.3'")
    list_parser.add_argument("--metadata", action="store_true", help="Print metadata for each package")
    list_parser.add_argument("--registry-url", nargs="*", dest="registry_urls", help="Registry URLs to list packages from. Overrides the default registry URLs.")
    list_parser.add_argument("--include-local", action="store_true", help="Include local extensions in the list. By default, only remote extensions are listed.")

    try:
        options = parser.parse_args()
        browse_exts(options)
    except SystemExit as e:
        pass
